import sys, math
input = sys.stdin.readline
INF = int(1000000000.0) + 7

def solve():
	s = input().rstrip()
	n = len(s)
	if n % 2 == 1:
		print('NO')
		return
	c = 0
	d = 0
	idx = -1
	for i in range(n):
		if s[i] == '?':
			d += 1
		elif s[i] == '(':
			c += 1
		else:
			c -= 1
	if d % 2 != c % 2 or abs(c) > d:
		print('NO')
		return
	if d == 0:
		print('YES')
		return
	if c >= 0:
		d = (d - c) // 2
	else:
		d = (d + c) // 2 - c
	a = [0] * n
	cur = 0
	for i in range(n):
		if s[i] == '(':
			cur += 1
		elif s[i] == ')':
			cur -= 1
		elif d:
			idx = i
			cur += 1
			d -= 1
		else:
			cur -= 1
		a[i] = cur
	ok = True
	if a[idx] < 2:
		ok = False
	for i in range(idx + 1, n):
		if s[i] == '?':
			if ok:
				print('NO')
				return
			else:
				break
		elif a[i] < 2:
			ok = False
	if n % 2 == 0 and a[n - 1] >= 0:
		print('YES')
		return
	print('NO')
t = 1
t = int(input())
for i in range(1, t + 1):
	solve()
